-- ============================================================================
-- 066_removals_table.sql
-- Single source of truth for the Cost Analysis job data.
--
-- Replaces the frozen src/data/removals.json export: every removal — the year
-- of history AND anything leadership adds/uploads later — lives here so it can
-- be edited, adjusted, or removed, with the analysis updating live.
--
-- TWO independent axes (see src/lib/cost-analysis.ts):
--   status  = the human switch. 'included' jobs are in the dataset; 'pending'
--             jobs await review; 'removed' jobs are hidden (recoverable).
--   the pricing (clean/comparable) subset is COMPUTED from the rules in
--             cost-analysis.ts (single tree, fully measured, above floor, …) —
--             it is NOT stored. Moving data here does not change that math.
--
-- Price is kept as TWO columns: original_price is the real billed amount and is
-- never overwritten; adjusted_price is leadership's optional override. The
-- analysis uses coalesce(adjusted_price, original_price).
--
-- Access is limited to the three Cost Analysis people (COST_ANALYSIS_EMAILS in
-- src/lib/auth.ts). Invoice numbers are intentionally NOT unique — historical
-- multi-line invoices legitimately repeat; duplicate prevention for NEW entries
-- is handled in app code.
-- ============================================================================

create table if not exists removals (
  id             uuid primary key default gen_random_uuid(),
  inv            text,
  haul           boolean not null default true,
  original_price numeric,
  adjusted_price numeric,
  dbh            numeric,
  stems          integer not null default 1,
  height         numeric,
  crown          numeric,
  species        text,
  seller         text,
  date           date,
  muni           boolean not null default false,
  kind           text not null default 'tree'  check (kind   in ('tree','stump','vine','shrub')),
  status         text not null default 'pending' check (status in ('included','pending','removed')),
  source         text not null default 'manual'  check (source in ('historical','manual','upload')),
  note           text,
  added_by       text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz,
  reviewed_by    text,
  reviewed_at    timestamptz,
  removed_by     text,
  removed_at     timestamptz
);

create index if not exists removals_status_idx on removals (status);
create index if not exists removals_inv_idx    on removals (inv);

alter table removals enable row level security;

-- Read + write limited to the three Cost Analysis people (keep in sync with
-- COST_ANALYSIS_EMAILS in src/lib/auth.ts).
drop policy if exists removals_read on removals;
create policy removals_read on removals
  for select using (
    lower(coalesce(auth.jwt() ->> 'email', '')) in
      ('molly@bratttree.com', 'connor@bratttree.com', 'caleb@bratttree.com')
  );

drop policy if exists removals_write on removals;
create policy removals_write on removals
  for all
  using (
    lower(coalesce(auth.jwt() ->> 'email', '')) in
      ('molly@bratttree.com', 'connor@bratttree.com', 'caleb@bratttree.com')
  )
  with check (
    lower(coalesce(auth.jwt() ->> 'email', '')) in
      ('molly@bratttree.com', 'connor@bratttree.com', 'caleb@bratttree.com')
  );

-- ----------------------------------------------------------------------------
-- Seed: the historical export (src/data/removals.json), all as included.
-- Re-runnable guard: only seed when the table has no historical rows yet.
-- ----------------------------------------------------------------------------
do $seed$
begin
  if not exists (select 1 from removals where source = 'historical') then
  end if;
end $seed$;
